<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount,onMounted} from 'vue'
import {freightLabel} from '../utils/freight'
import {previewEmployeeFreight,resolveEmployeeShippingDestination,fetchEmployeeFreightRegions,fetchEmployeeFreightTemplates,type FreightSnapshot} from '../api/customerPortal'
import {emptyFreightState,freightAmount,freightOverride,missingWeightItemNames,regionDestination,searchOrderRegions,type FreightState,type FreightRegion} from '../utils/orderFreight'
const props=defineProps<{token:string;customerId:number;modelValue?:FreightState;address?:string;orderId?:number;expectedToken?:string;locked?:boolean;storedQuote?:FreightSnapshot;items:{product_id:number;bom_spec_id?:number;bom_variant_id?:number;qty:number;name?:string}[]}>()
const emit=defineEmits<{(e:'update:modelValue',v:FreightState):void;(e:'amount-change',v:number):void}>()
const state=ref<FreightState>({...emptyFreightState(),...props.modelValue}),quote=ref<FreightSnapshot|undefined>(props.storedQuote),busy=ref(false),error=ref(''),query=ref(''),searchOpen=ref(false),regions=ref<FreightRegion[]>([]),templates=ref<{id:number;name:string;active:boolean;revision:number;packaging_weight_g:number}[]>([])
let addressTask:Promise<void>=Promise.resolve()
let sequence=0,addressSequence=0,alive=true,timer:ReturnType<typeof setTimeout>|undefined,lastItems=JSON.stringify(props.items)
const regionLabel=computed(()=>[state.value.destination.province,state.value.destination.city,state.value.destination.district].filter(Boolean).join(' / ')),matches=computed(()=>searchOrderRegions(regions.value,query.value).slice(0,80)),templateNames=computed(()=>templates.value.map(t=>t.name)),templateIndex=computed(()=>Math.max(0,templates.value.findIndex(t=>t.id===Number(state.value.templateId||quote.value?.template_id||quote.value?.policy?.template_id)))),missingWeightItems=computed(()=>missingWeightItemNames(props.items,quote.value))
function update(patch:Partial<FreightState>,activate=false){const next={...state.value,...patch,autoAmountCents:('manual'in patch||'free'in patch||'parcelWeightG'in patch||'templateOverride'in patch)?null:state.value.autoAmountCents};if(activate){next.preserveExisting=false;if('manual'in patch)next.chargeMode=String(patch.manual||'').trim()?'manual_current':'auto_current';else if('free'in patch)next.chargeMode=patch.free?'free':'auto_current';else next.chargeMode='auto_current'}state.value=next;emit('update:modelValue',state.value);try{emit('amount-change',freightAmount(state.value))}catch{}}
function selectTemplate(event:{detail:{value:string|number}}){const row=templates.value[Number(event.detail.value)];if(row)update({templateId:row.id,templateOverride:true,manual:'',free:false},true)}
function restoreAuto(){update({manual:'',free:false,chargeMode:'auto_current',autoAmountCents:null},true)}
function inputAmount(event:Event){const e=event as unknown as {detail:{value:string}};update({manual:e.detail.value},true)}
function inputParcelWeight(event:Event){const e=event as unknown as {detail:{value:string}};update({parcelWeightG:e.detail.value,manual:'',free:false},true)}
function toggleFree(event:Event){const e=event as unknown as {detail:{value:boolean}};update({free:e.detail.value},true)}
function selectRegion(code:string){addressSequence++;update({destination:regionDestination(regions.value,code),source:'manual',address:props.address||''},true);query.value='';searchOpen.value=false;error.value=''}
async function resolveAddress(){const current=++addressSequence;if(props.locked||!props.address||state.value.address===props.address&&state.value.destination.province)return;try{const r=await resolveEmployeeShippingDestination(props.token,props.address);if(!alive||current!==addressSequence)return;if(r.status==='resolved'){update({destination:r.destination,address:props.address,source:'auto'})}else{update({destination:emptyFreightState().destination,address:props.address,source:'auto'});error.value='收件地区无法唯一识别，请搜索选择'}}catch(e){if(alive&&current===addressSequence)error.value=e instanceof Error?e.message:'地址识别失败'}}
async function preview(){await addressTask;if(timer)clearTimeout(timer);if(props.locked)return props.storedQuote||null;if(props.orderId&&state.value.preserveExisting){quote.value=props.storedQuote;emit('amount-change',freightAmount(state.value));return quote.value||null}const current=++sequence;quote.value=undefined;error.value='';if(!props.customerId||!props.items.length){busy.value=false;return null}busy.value=true;try{const q=await previewEmployeeFreight(props.token,{customer_id:props.customerId,freight_protocol:'order_freight_v2',order_id:props.orderId||0,expected_freight_token:props.expectedToken||'',...state.value.destination,items:props.items,freight_override:freightOverride(state.value)});if(!alive||current!==sequence)return null;if(state.value.free==null&&q.policy?.free_shipping)state.value={...state.value,free:true};if(!state.value.manual&&!state.value.free)state.value={...state.value,autoAmountCents:q.current_receivable_cents??null};quote.value=q;emit('update:modelValue',state.value);emit('amount-change',freightAmount(state.value));return q}catch(e){if(alive&&current===sequence)error.value=e instanceof Error?e.message:'运费核算失败';return null}finally{if(alive&&current===sequence)busy.value=false}}
function payload(){const preserve=!!props.orderId&&state.value.preserveExisting;return {freight_protocol:preserve?'':'order_freight_v2',freight_quote_token:preserve?'':quote.value?.token||'',expected_freight_token:preserve?'':props.expectedToken||'',shipping_province:state.value.destination.province,shipping_city:state.value.destination.city,shipping_district:state.value.destination.district,...(preserve?{}:{freight_override:freightOverride(state.value)}),shipping_amount:freightAmount(state.value)}}
function invalidate(){if(props.locked){quote.value=props.storedQuote;return;}sequence++;quote.value=undefined;busy.value=false;if(timer)clearTimeout(timer);if(!props.locked)timer=setTimeout(()=>void preview(),450)}
watch(()=>props.modelValue,v=>{if(v&&JSON.stringify(v)!==JSON.stringify(state.value))state.value=v},{deep:true})
watch(()=>[props.customerId,JSON.stringify(props.items),props.orderId,props.expectedToken,state.value.manual,state.value.free,state.value.chargeMode,state.value.templateId,state.value.templateOverride,state.value.parcelWeightG,state.value.preserveExisting,JSON.stringify(state.value.destination)],invalidate)
watch(()=>JSON.stringify(props.items),next=>{if(next!==lastItems){lastItems=next;if(state.value.parcelWeightG)update({parcelWeightG:''})}})
watch(()=>props.customerId,(next,previous)=>{if(previous>0&&next!==previous){addressSequence++;update(emptyFreightState());addressTask=resolveAddress()}})
watch(()=>props.address,()=>addressTask=resolveAddress(),{immediate:true})
onMounted(async()=>{try{const r=await fetchEmployeeFreightRegions(props.token);if(alive)regions.value=r.regions||[]}catch(e){if(alive)error.value=e instanceof Error?e.message:'地区加载失败'}try{const r=await fetchEmployeeFreightTemplates(props.token);if(alive)templates.value=(r.templates||[]).filter(t=>t.active)}catch(e){if(alive)error.value=e instanceof Error?e.message:'运费模板读取失败'}if(props.customerId&&props.items.length)invalidate()})
onBeforeUnmount(()=>{alive=false;sequence++;addressSequence++;if(timer)clearTimeout(timer)})
defineExpose({preview,payload})
</script>
<template>
 <view class="estimate-card"><text class="title">运费</text>
 <text v-if="locked" class="hint">运费已出账或已确认实际费用，收费规则已锁定。</text>
 <template v-else>
  <view class="field" @tap="searchOpen=!searchOpen">{{regionLabel||'选择收件省市区'}} ›</view>
  <view v-if="searchOpen"><input v-model="query" class="field" placeholder="搜索省市区，如孟连县" /><scroll-view scroll-y class="region-options"><view v-for="r in matches" :key="r.code" class="region-row" @tap="selectRegion(r.code)">{{r.path||r.name}}</view><text v-if="!matches.length" class="hint">没有符合条件的地区</text></scroll-view></view>
  <text class="label">本单运费模板</text><picker mode="selector" :range="templateNames" :value="templateIndex" @change="selectTemplate"><view class="field">{{templateNames[templateIndex]||'读取运费模板中'}} ›</view></picker>
  <text class="label">本单运费（元，留空自动）</text><input :value="state.manual" :disabled="!!state.free" type="digit" class="field" placeholder="留空自动" @input="inputAmount" />
  <button v-if="state.preserveExisting||state.manual||state.free||state.chargeMode==='deferred'" @tap="restoreAuto">恢复自动计算</button>
  <text class="label">本单包裹总重量（克，含包装）</text><input :value="state.parcelWeightG" type="number" class="field" placeholder="缺少商品物流重量时填写" @input="inputParcelWeight" />
  <view class="switch"><text>包邮</text><switch :checked="!!state.free" @change="toggleFree" /></view>
 </template>
 <text v-if="error" class="error">{{error}}</text><text v-else-if="busy" class="hint">正在核算运费…</text><text v-else-if="state.preserveExisting" class="hint">保留当前订单运费 ¥{{freightAmount(state).toFixed(2)}}</text><text v-else-if="quote" class="amount">{{freightLabel(quote)}}</text><text v-else class="hint">{{customerId&&items.length?'准备核算运费…':'添加商品后自动计算'}}</text>
 <text v-if="missingWeightItems.length" class="error">以下商品缺少物流重量：{{missingWeightItems.join('、')}}。请填写本单含包装的包裹总重量后核算。</text>
 <text v-if="!state.free && !state.manual" class="hint">自动计算运费计入本单应收；实际账单出账后按已收金额核对。</text><text v-else-if="!state.free" class="hint">手填运费计入本单应收，实际账单出账后按已收金额核对。</text>
 <text v-if="quote && !quote.estimate_known && quote.cost_pending_reason" class="hint">{{quote.cost_pending_reason}}</text>
 <button v-if="error&&!locked" @tap="preview">重试核算</button></view>
</template>
<style scoped>
.estimate-card{padding:24rpx;background:#eff6f0;border:1px solid #d5e5d9;border-radius:14rpx;margin:24rpx 0}.title{font-size:30rpx;font-weight:700;color:#244c36}.field{margin-top:16rpx;padding:20rpx;background:white;border:1px solid #cbd9cf;border-radius:10rpx;font-size:28rpx}.label{display:block;margin-top:20rpx;font-size:26rpx}.hint,.error,.amount{display:block;font-size:25rpx;line-height:1.7;margin:12rpx 0}.hint{color:#718276}.error{color:#b13b2f}.amount{color:#286248;font-weight:600}.switch{display:flex;align-items:center;justify-content:space-between;font-size:26rpx;margin:10rpx 0}button{font-size:26rpx;color:#286248;background:white;border:1px solid #cbd9cf;margin-top:14rpx}.region-options{max-height:420rpx}.region-row{padding:20rpx 8rpx;border-bottom:1px solid #d5e5d9;font-size:26rpx}
</style>
